<?php
require_once __DIR__.'/_common.php';
$rows=sponsor_rows($conn,"SELECT c.id,c.name,c.status,c.start_date,c.end_date,c.max_capacity,c.applications_count,c.location,c.province,c.delivery_mode,p.name programme_name FROM cohorts c LEFT JOIN programmes p ON p.id=c.programme_id ORDER BY FIELD(c.status,'active','open','closed','draft','completed','archived'),c.start_date DESC,c.name");
sponsor_header('Cohort register','cohorts','Review intakes, delivery arrangements, dates and planned capacity.'); ?>
<div class="sp-card"><div class="sp-toolbar"><input class="sp-search" data-search="#cohortTable" placeholder="Search cohort, programme, province…" aria-label="Search cohorts"><select class="sp-select" data-filter-status><option value="">All statuses</option><?php foreach(['active','open','closed','draft','completed','archived'] as $s): ?><option value="<?= $s ?>"><?= sponsor_e(sponsor_status($s)) ?></option><?php endforeach; ?></select><a class="sp-btn" href="<?= url('sponsor/export.php?dataset=cohorts') ?>">↓ Export CSV</a></div><div class="sp-tablewrap"><table id="cohortTable"><thead><tr><th>Cohort / intake</th><th>Programme</th><th>Status</th><th>Capacity</th><th>Applications*</th><th>Delivery</th><th>Location</th><th>Dates</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr data-status-row="<?= sponsor_e($r['status']) ?>"><td><strong><?= sponsor_e($r['name']) ?></strong></td><td><?= sponsor_e($r['programme_name']??'—') ?></td><td><span class="sp-pill <?= sponsor_e($r['status']) ?>"><?= sponsor_e(sponsor_status((string)$r['status'])) ?></span></td><td><?= number_format((int)$r['max_capacity']) ?></td><td><?= number_format((int)$r['applications_count']) ?></td><td><?= sponsor_e(sponsor_status((string)$r['delivery_mode'])) ?></td><td><?= sponsor_e(trim(($r['location']??'').' '.($r['province']??''))?:'—') ?></td><td><?= sponsor_e(sponsor_date($r['start_date'])) ?><br><span class="sp-muted">to <?= sponsor_e(sponsor_date($r['end_date'])) ?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="sp-empty">No cohort records found.</td></tr><?php endif; ?></tbody></table></div></div><p class="sp-footnote">*Application counts are the cohort-level value maintained by the application. This portal does not change cohort records.</p><?php sponsor_footer(); ?>
